var qb=document.getElementById('quizbox'),qi=0,sc=0,order=[],cur=null,curKey='',tm=null,wrong=[];
function shuffle(a){for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t}return a}
function store(k,v){try{if(v===undefined)return JSON.parse(localStorage.getItem('pm-'+k)||'null');localStorage.setItem('pm-'+k,JSON.stringify(v))}catch(e){return null}}
function hist(){return store('hist')||{}}
function errs(){return store('errs')||[]}
function best(k){var h=hist()[k];return h?Math.max.apply(null,h.map(function(x){return x[1]})):0}
function menu(){
 clearInterval(tm);EX=null;
 qb.innerHTML='<p>Choisis un niveau. Pour chaque question, sélectionne une réponse puis valide ton choix avant la fin du temps.</p><div class="cards" id="lvls"></div><div id="prog"></div>';
 var box=document.getElementById('lvls');
 Object.keys(LV).forEach(function(k){
  var l=LV[k],n=l.idx?l.idx.length:Q.length,h=hist()[k]||[];
  var b=document.createElement('button');b.className='fc';
  b.innerHTML='<strong></strong><span></span><br><small></small>';
  b.querySelector('strong').textContent=l.nom;
  b.querySelector('span').textContent=l.desc;
  b.querySelector('small').textContent=n+' questions · '+l.sec+' s par question'+(h.length?' · meilleur score : '+best(k)+' / '+n:'');
  b.onclick=function(){start(k)};
  box.appendChild(b);
 });
  var eb=document.createElement('button');eb.className='fc exam';eb.innerHTML='<strong>Examen blanc</strong><span>20 questions au hasard, 20 minutes en tout, une note sur 20 et le corrigé.</span>';eb.onclick=startExam;box.insertBefore(eb,box.firstChild);
 progress();
}
function progress(){
 var p=document.getElementById('prog');if(!p)return;p.innerHTML='';
 var h=hist(),e=errs();
 p.appendChild(el('h2',null,'Mon avancement'));
 var keys=Object.keys(LV).filter(function(k){return h[k]&&h[k].length});
 if(!keys.length&&!e.length&&!(store('exam')||[]).length){p.appendChild(el('p','foot','Fais un premier quiz : tes scores et les questions à revoir apparaîtront ici. Ils sont gardés sur cet appareil, dans ce navigateur.'));return}
 if(keys.length){var sw=el('div','scroll'),t=el('table');sw.appendChild(t);
  var tr=el('tr');['Niveau','Tentatives','Meilleur score','Dernier score','Dernière fois'].forEach(function(x){tr.appendChild(el('th',null,x))});t.appendChild(tr);
  keys.forEach(function(k){var a=h[k],last=a[a.length-1],n=last[2];var r=el('tr');
   [LV[k].nom,a.length,best(k)+' / '+n,last[1]+' / '+n,new Date(last[0]).toLocaleDateString('fr-FR')].forEach(function(x){r.appendChild(el('td',null,String(x)))});t.appendChild(r)});
  p.appendChild(sw)}
 var ex=store('exam')||[];if(ex.length){var bx=Math.max.apply(null,ex.map(function(x){return x[1]})),lx=ex[ex.length-1];p.appendChild(el('p',null,'Examen blanc : '+ex.length+' passage'+(ex.length>1?'s':'')+' · meilleure note '+bx+'/20 · dernière note '+lx[1]+'/20 ('+new Date(lx[0]).toLocaleDateString('fr-FR')+').'))}
 var row=el('div','tools');
 if(e.length){var b=el('button','go','Revoir mes erreurs ('+e.length+' question'+(e.length>1?'s':'')+')');b.type='button';b.onclick=function(){start('revoir')};row.appendChild(b)}
 else row.appendChild(el('p','foot','Aucune question à revoir pour l’instant.'));
 var z=el('button','go ghost','Remettre à zéro');z.type='button';z.onclick=function(){if(z.dataset.ok){store('hist',{});store('errs',[]);store('exam',[]);menu()}else{z.dataset.ok=1;z.textContent='Confirmer la remise à zéro'}};row.appendChild(z);
 p.appendChild(row);
}
function start(k){
 if(k==='revoir'){var e=errs();if(!e.length){menu();return}cur={nom:'Mes erreurs',sec:45,idx:e.slice()};}
 else cur=LV[k];
 curKey=k;wrong=[];
 order=shuffle((cur.idx||Q.map(function(_,i){return i})).slice());qi=0;sc=0;show();
}
function show(){
 clearInterval(tm);
 if(qi>=order.length){
  if(curKey!=='revoir'){var h=hist();(h[curKey]=h[curKey]||[]).push([Date.now(),sc,order.length]);if(h[curKey].length>30)h[curKey].shift();store('hist',h)}
  var b=curKey==='revoir'?sc:best(curKey);
  qb.innerHTML='<div class="box"><div class="big">'+sc+' / '+order.length+'</div><p>'+(curKey==='revoir'?'Révision de tes erreurs. Les questions réussies sont retirées de ta liste.':'Niveau '+cur.nom.toLowerCase()+'. Meilleur score : '+b+' / '+order.length)+'</p><div id="rev"></div><button class="go" id="again">Recommencer</button> <button class="go" id="men" style="background:var(--ink);color:var(--bg)">Changer de niveau</button></div>';
  if(wrong.length){var r=document.getElementById('rev');r.innerHTML='<h3>À revoir</h3><ul></ul>';wrong.forEach(function(w){var li=document.createElement('li');li.textContent=w;r.querySelector('ul').appendChild(li)})}
  document.getElementById('again').onclick=function(){start(curKey)};
  document.getElementById('men').onclick=menu;return;
 }
 var qn=order[qi],q=Q[qn],sel=-1,locked=false,left=cur.sec;
 qb.innerHTML='<div class="bar"><i style="width:'+(qi/order.length*100)+'%"></i></div><div>'+cur.nom+' · question '+(qi+1)+' sur '+order.length+'</div><div class="tm" id="tm" role="timer"></div><div class="bar tbar"><i id="tb" style="width:100%"></i></div><div class="q"></div><div id="opts"></div><button class="go" id="val" disabled>Valider</button><div class="fb" id="fb" aria-live="polite"></div>';
 qb.querySelector('.q').textContent=q[0];
 var o=document.getElementById('opts'),val=document.getElementById('val'),fb=document.getElementById('fb'),tmEl=document.getElementById('tm'),tb=document.getElementById('tb');
 var opts=shuffle(q[1].map(function(t,i){return{t:t,i:i}}));
 var btns=opts.map(function(x,k){
  var b=document.createElement('button');b.className='opt';b.textContent=x.t;b.setAttribute('aria-pressed','false');
  b.onclick=function(){if(locked)return;sel=k;btns.forEach(function(y,m){y.classList.toggle('sel',m===k);y.setAttribute('aria-pressed',m===k)});val.disabled=false};
  o.appendChild(b);return b;
 });
 function reveal(timeout){
  locked=true;clearInterval(tm);val.hidden=true;
  btns.forEach(function(b,k){b.disabled=true;b.classList.remove('sel');if(opts[k].i===q[2])b.classList.add('ok')});
  var good=!timeout&&sel>-1&&opts[sel].i===q[2],e=errs();
  if(good){sc++;if(e.indexOf(qn)>-1){e.splice(e.indexOf(qn),1);store('errs',e)}}
  else{if(sel>-1&&!timeout)btns[sel].classList.add('ko');wrong.push(q[0]+' → '+q[1][q[2]]);if(e.indexOf(qn)<0){e.push(qn);store('errs',e)}}
  fb.textContent=(good?'Bonne réponse. ':timeout?'Temps écoulé. ':'Pas tout à fait. ')+q[3];
  var n=document.createElement('button');n.className='go';n.textContent=qi+1<order.length?'Question suivante':'Voir mon score';
  n.onclick=function(){qi++;show()};fb.appendChild(document.createElement('br'));fb.appendChild(n);n.focus();
 }
 val.onclick=function(){if(sel>-1&&!locked)reveal(false)};
 function tick(){tmEl.textContent='Temps restant : '+left+' s';tmEl.classList.toggle('low',left<=10);tb.style.width=(left/cur.sec*100)+'%'}
 tick();
 tm=setInterval(function(){left--;tick();if(left<=0){reveal(true)}},1000);
}

