  var la=pos.coords.latitude,lo=pos.coords.longitude;
  if(map){map.setView([la,lo],12);if(meMk)map.removeLayer(meMk);meMk=L.circleMarker([la,lo],{radius:8,color:'#fff',weight:2,fillColor:'#CE1126',fillOpacity:1}).addTo(map).bindTooltip('Tu es ici')}
  var near=[];PM.forEach(function(c){var best=Infinity;(c[13].length?c[13].map(function(p){return[p[3],p[4]]}):[[c[3],c[4]]]).forEach(function(p){best=Math.min(best,dist(la,lo,p[0],p[1]))});near.push([best,c])});
  near.sort(function(a,b){return a[0]-b[0]});
  out.innerHTML='';out.appendChild(document.createTextNode('Les plus proches : '));
  near.slice(0,5).forEach(function(x,i){var a=el('a',null,x[1][1]+' ('+(x[0]<1?Math.round(x[0]*1000)+' m':x[0].toFixed(1).replace('.',',')+' km')+')');a.href='#';a.onclick=function(e){e.preventDefault();openCommune(x[1][0])};out.appendChild(a);if(i<4)out.appendChild(document.createTextNode(' · '))});
