function fmtN(n,d){return Number(n).toLocaleString('fr-FR',{maximumFractionDigits:d||0,minimumFractionDigits:d||0})}
/* ---------- Favoris ---------- */
function favs(){return store('fav')||[]}
function isFav(t,id){return favs().some(function(f){return f.t===t&&f.id===id})}
function favBtn(t,id,label){
 var b=el('button','star');b.type='button';
 function upd(){var on=isFav(t,id);b.textContent=on?'★':'☆';b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',(on?'Retirer des favoris : ':'Ajouter aux favoris : ')+label);b.title=on?'Retirer des favoris':'Ajouter aux favoris'}
 b.onclick=function(e){e.stopPropagation();var f=favs(),i=f.findIndex(function(x){return x.t===t&&x.id===id});if(i>-1)f.splice(i,1);else f.push({t:t,id:id,l:label,d:Date.now()});store('fav',f);upd();renderFav()};
 upd();return b}
var FAVT={texte:'Textes de lois',fiche:'Fiches mémo',commune:'Communes',puisje:'Est-ce que je peux… ?'};
function openFav(f){
 if(f.t==='commune')openCommune(f.id);
 else if(f.t==='fiche'){go('fiches');setTimeout(function(){var x=document.getElementById('f-'+f.id);if(x)x.scrollIntoView()},50)}
 else if(f.t==='texte'){go('biblio');var q=document.getElementById('libQ');if(q){q.value=f.id;q.dispatchEvent(new Event('input'))}}
 else if(f.t==='puisje'){go('puisje');showPJ(f.id)}
}
function renderFav(){
 var box=document.getElementById('favList');if(!box)return;box.innerHTML='';var f=favs();
 if(!f.length){box.appendChild(el('p','foot','Aucun favori pour l’instant.'));return}
 Object.keys(FAVT).forEach(function(t){var it=f.filter(function(x){return x.t===t});if(!it.length)return;
  box.appendChild(el('h3',null,FAVT[t]+' ('+it.length+')'));var ul=el('ul','sres');
  it.forEach(function(x){var li=el('li','favrow');var a=el('a',null,x.l);a.href='#';a.onclick=function(e){e.preventDefault();openFav(x)};li.appendChild(a);li.appendChild(favBtn(x.t,x.id,x.l));ul.appendChild(li)});box.appendChild(ul)});
}
