function selNote(id){curN=id;var n=NOTES.find(function(x){return x.id===id});document.getElementById('nTitle').value=n?n.t:'';document.getElementById('nBody').value=n?n.b:'';document.getElementById('nSaved').textContent='';drawNotes()}
