['nTitle','nBody'].forEach(function(i){document.getElementById(i).addEventListener('input',function(){var n=NOTES.find(function(x){return x.id===curN});if(!n)return;n.t=document.getElementById('nTitle').value;n.b=document.getElementById('nBody').value;n.u=Date.now();clearTimeout(nT);nT=setTimeout(function(){saveNotes();drawNotes()},400)})});
document.getElementById('nDel').onclick=function(){var b=this;if(!b.dataset.ok){b.dataset.ok=1;b.textContent='Confirmer la suppression';setTimeout(function(){b.dataset.ok='';b.textContent='Supprimer'},4000);return}
 NOTES=NOTES.filter(function(x){return x.id!==curN});curN=null;saveNotes();document.getElementById('nTitle').value='';document.getElementById('nBody').value='';b.dataset.ok='';b.textContent='Supprimer';drawNotes()};
document.getElementById('nExport').onclick=function(){var n=NOTES.find(function(x){return x.id===curN});if(!n)return;var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([(n.t||'Note')+'\n\n'+n.b],{type:'text/plain;charset=utf-8'}));a.download=((n.t||'note').replace(/[^\wÀ-ÿ -]/g,'').trim()||'note')+'.txt';document.body.appendChild(a);a.click();a.remove()};
drawNotes();
/* ---------- Graphiques ---------- */
var TIP=el('div','tip');TIP.hidden=true;document.body.appendChild(TIP);
function tipAt(e,txt){TIP.textContent=txt;TIP.hidden=false;var x=Math.min(e.clientX+14,window.innerWidth-TIP.offsetWidth-8),y=e.clientY-TIP.offsetHeight-10;TIP.style.left=x+'px';TIP.style.top=(y<8?e.clientY+16:y)+'px'}
function hideTip(){TIP.hidden=true}
function lineChart(box,pts,unit){
 box.innerHTML='';var W=640,H=250,L=56,R=16,T=16,B=32;var max=Math.max.apply(null,pts.map(function(p){return p[1]}));
 var step=Math.pow(10,Math.floor(Math.log10(max)));var top=Math.ceil(max*1.08/step)*step;if(top/step>8){step*=2;top=Math.ceil(max*1.08/step)*step}
 var X=function(i){return L+(W-L-R)*(pts.length===1?.5:i/(pts.length-1))},Y=function(v){return T+(H-T-B)*(1-v/top)};
 var s='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+unit+' par année"><g class="grid">';
 for(var v=0;v<=top;v+=step)s+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+Y(v)+'" y2="'+Y(v)+'"/><text x="'+(L-8)+'" y="'+(Y(v)+4)+'" text-anchor="end">'+fmtN(v)+'<\/text>';
 s+='<\/g><g class="xax">';pts.forEach(function(p,i){s+='<text x="'+X(i)+'" y="'+(H-10)+'" text-anchor="middle">'+p[0]+'<\/text>'});s+='<\/g>';
 s+='<path class="ln" d="'+pts.map(function(p,i){return(i?'L':'M')+X(i)+','+Y(p[1])}).join('')+'"/>';
 pts.forEach(function(p,i){s+='<circle class="pt" cx="'+X(i)+'" cy="'+Y(p[1])+'" r="4.5"/>'});
 var last=pts[pts.length-1];s+='<text class="lbl" x="'+(X(pts.length-1)-6)+'" y="'+(Y(last[1])-12)+'" text-anchor="end">'+fmtN(last[1])+'<\/text>';
 pts.forEach(function(p,i){var w=(W-L-R)/Math.max(1,pts.length-1);s+='<rect class="hit" data-i="'+i+'" x="'+(X(i)-w/2)+'" y="'+T+'" width="'+w+'" height="'+(H-T-B)+'"/>'});
 s+='<line class="cross" x1="0" x2="0" y1="'+T+'" y2="'+(H-B)+'" visibility="hidden"/><\/svg>';box.innerHTML=s;
 var cr=box.querySelector('.cross');
 box.querySelectorAll('.hit').forEach(function(h){var i=+h.dataset.i;h.addEventListener('mousemove',function(e){cr.setAttribute('x1',X(i));cr.setAttribute('x2',X(i));cr.setAttribute('visibility','visible');tipAt(e,pts[i][0]+' : '+fmtN(pts[i][1])+' '+unit)});h.addEventListener('mouseleave',function(){cr.setAttribute('visibility','hidden');hideTip()})});
}
function barChart(box,rows,fmtv,onClick){
 box.innerHTML='';var max=Math.max.apply(null,rows.map(function(r){return Math.abs(r[1])}))||1;
 rows.forEach(function(r){var row=el('button','brow');row.type='button';row.appendChild(el('span','bl',r[0]));var tr=el('span','bt');var b=el('i');b.style.width=(Math.abs(r[1])/max*100)+'%';if(r[1]<0)b.className='neg';tr.appendChild(b);row.appendChild(tr);row.appendChild(el('span','bv',fmtv(r[1])));
  row.onmousemove=function(e){tipAt(e,r[0]+' : '+fmtv(r[1]))};row.onmouseleave=hideTip;row.onclick=function(){hideTip();onClick(r[2])};box.appendChild(row)});
}
