 [[fmtN(n24[0]),'agents de police municipale (2024)'],['+'+fmtN((n24[0]/n15[0]-1)*100)+' %','d’agents depuis 2015'],[fmtN(n24[1]),'ASVP (2024)'],[fmtN(PM.filter(function(c){return c[5]!=null}).length),'communes avec un service (2024)']].forEach(function(s){var d=el('div','stat');d.appendChild(el('b',null,s[0]));d.appendChild(el('span',null,s[1]));t.appendChild(d)});
