var NAVS=document.querySelectorAll('main > section'),mBtn=document.getElementById('menuBtn'),mPanel=document.getElementById('menuPanel'),mLinks=mPanel.querySelectorAll('a'),curId='accueil';
function setMenu(o){mPanel.hidden=!o;mBtn.setAttribute('aria-expanded',o?'true':'false');mBtn.setAttribute('aria-label',o?'Fermer le menu':'Ouvrir le menu')}
function go(id){
 var el=document.getElementById(id);
 if(!el||el.parentNode.nodeName!=='MAIN')id='accueil';
 if(curId==='quiz'&&id!=='quiz')menu();
 if(id==='commune'&&!document.getElementById('fiche').firstChild)id='carte';
 if(id==='departement'&&!document.getElementById('depFiche').firstChild)id='tableau';
 if(id==='notes')drawNotes();if(id==='favoris')renderFav();
 curId=id;
 NAVS.forEach(function(s){s.hidden=s.id!==id});
 if(id==='carte')ensureData(initMap);
 var mt=(typeof GROUP_OF!=='undefined'&&GROUP_OF[id])||id;if(id==='mindmaps'&&typeof renderMaps==='function')renderMaps();if(typeof showSubnavCur==='function')setTimeout(function(){showSubnavCur(id)},0);
 mLinks.forEach(function(a){if(a.getAttribute('data-t')===mt)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 setMenu(false);window.scrollTo(0,0);
}
mBtn.addEventListener('click',function(){setMenu(mPanel.hidden)});
document.addEventListener('click',function(e){
 var a=e.target.closest?e.target.closest('[data-go]'):null;
 if(a){e.preventDefault();var id=a.getAttribute('data-go');go(id);try{history.replaceState(null,'','#'+id)}catch(x){}return}
 if(!mPanel.hidden&&!mPanel.contains(e.target)&&!mBtn.contains(e.target))setMenu(false);
});
document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!mPanel.hidden){setMenu(false);mBtn.focus()}});
