function buildSubnav(){
 Object.keys(GROUPS).forEach(function(g){
  var G=GROUPS[g];
  G.p.concat([['commune'],['departement']]).forEach(function(x){
   var sec=document.getElementById(x[0]);if(!sec||GROUP_OF[x[0]]!==g||sec.querySelector('.subnav'))return;
   var nav=document.createElement('nav');nav.className='subnav noprint';nav.setAttribute('aria-label','Pages de l’espace '+G.n);
   var c=document.createElement('a');c.className='sn-back';c.href='#'+g;c.setAttribute('data-go',g);c.textContent='← '+G.n;nav.appendChild(c);
   var row=document.createElement('div');row.className='sn-row';
   var cur=x[0]==='commune'?'carte':x[0]==='departement'?'tableau':x[0];
   G.p.forEach(function(y){var a=document.createElement('a');a.href='#'+y[0];a.setAttribute('data-go',y[0]);a.textContent=y[1];if(y[0]===cur)a.setAttribute('aria-current','page');row.appendChild(a)});
   nav.appendChild(row);sec.insertBefore(nav,sec.firstChild);
  });
 });
}
