/* ---------- Téléchargement de fichiers ---------- */
async function saveFile(name,data,mime){
 try{
  var d=(window.claude&&claude.use)?await claude.use('downloads'):null;
  if(d){await d.save({filename:name,data:data});return 'saved'}
  if(window.claude)return 'unavail';
 }catch(e){
  if(e&&e.code==='declined')return 'declined';
  if(e&&e.code==='rate_limited')return 'busy';
 }
 try{
  var blob=data instanceof Blob?data:new Blob([data],{type:mime||'application/octet-stream'});
  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();
  setTimeout(function(){URL.revokeObjectURL(a.href);a.remove()},4000);return 'saved';
 }catch(e){return 'error'}
}
function saveMsg(r,el,ok){el.textContent=r==='saved'?ok:r==='declined'?'Téléchargement annulé.':r==='busy'?'Une demande est déjà ouverte, réessaie dans un instant.':r==='unavail'?'Le téléchargement direct n’est pas disponible ici. Ouvre la carte en grand (clic sur l’aperçu), puis fais un clic droit ou un appui long sur l’image et choisis « Enregistrer l’image ».':'Le téléchargement a échoué. Réessaie.'}
document.getElementById('nExport').onclick=async function(){var n=NOTES.find(function(x){return x.id===curN});if(!n)return;var r=await saveFile(((n.t||'note').replace(/[^\wÀ-ÿ -]/g,'').trim()||'note')+'.txt',(n.t||'Note')+'\n\n'+n.b,'text/plain;charset=utf-8');saveMsg(r,document.getElementById('nSaved'),'Note téléchargée.')};

/* ---------- Cartes mentales ---------- */
function wrapTxt(t,n){var w=String(t).split(/\s+/),L=[],c='';w.forEach(function(x){if((c+' '+x).trim().length>n&&c){L.push(c);c=x}else c=(c+' '+x).trim()});if(c)L.push(c);return L}
var MMCOL={'Codes':'#0f766e','Lois':'#1d4ed8','Décrets et arrêtés':'#157a47','Articles':'#7c3aed'};
function catSvg(title,cats,col){
 var items=LIB.filter(function(x){return cats.indexOf(x[0])>-1});
 var ncol=items.length>13?2:1,BW=640,LH=19,PADY=12,GAP=12,TOPY=96;
 var per=Math.ceil(items.length/ncol),boxes=[];
 items.forEach(function(it,i){
  var lab=wrapTxt(it[1].replace(/ \(non adopté à ce jour\)/,' (non adopté)'),58),des=wrapTxt(it[2],78);
  if(des.length>2){des=des.slice(0,2);des[1]=des[1].replace(/[ ,.;:]*$/,'')+'…'}
  boxes.push({lab:lab,des:des,h:PADY*2+lab.length*21+des.length*LH,c:Math.floor(i/per)});
 });
 var colH=[0,0];boxes.forEach(function(b){b.y=TOPY+colH[b.c];colH[b.c]+=b.h+GAP});
 var CW=330,H=Math.max(colH[0],colH[1]-GAP)+TOPY+40,W,CX,XS;
 if(ncol===2){W=40+BW+60+CW+60+BW+40;XS=[40,40+BW+60+CW+60];CX=40+BW+60}else{W=40+CW+70+BW+40;CX=40;XS=[40+CW+70]}
 var cy=Math.max(TOPY+80,(TOPY+H-40)/2),out='',links='';
 boxes.forEach(function(b){
  var x=XS[ncol===2?b.c:0],my=b.y+b.h/2,left=ncol===2&&b.c===0;
  var sx=left?CX:CX+CW,ex=left?x+BW:x,mx=(sx+ex)/2;
  links+='<path d="M'+sx+','+cy+' C'+mx+','+cy+' '+mx+','+my+' '+ex+','+my+'" fill="none" stroke="'+col+'" stroke-width="3" opacity=".7"/>';
  out+='<rect x="'+x+'" y="'+b.y+'" width="'+BW+'" height="'+b.h+'" rx="10" fill="#fff" stroke="'+col+'" stroke-width="2"/><rect x="'+(left?x+BW-7:x)+'" y="'+b.y+'" width="7" height="'+b.h+'" rx="3" fill="'+col+'"/>';
  var ty=b.y+PADY+15;
  b.lab.forEach(function(l){out+='<text x="'+(x+20)+'" y="'+ty+'" font-size="16" font-weight="700" fill="#14233c">'+esc(l)+'</text>';ty+=21});
  b.des.forEach(function(l){out+='<text x="'+(x+20)+'" y="'+ty+'" font-size="14" fill="#4b5873">'+esc(l)+'</text>';ty+=LH});
 });
 var tl=wrapTxt(title,16);
 var center='<rect x="'+CX+'" y="'+(cy-70)+'" width="'+CW+'" height="140" rx="70" fill="#14233c" stroke="'+col+'" stroke-width="6"/>';
 tl.forEach(function(l,i){center+='<text x="'+(CX+CW/2)+'" y="'+(cy+10-(tl.length-1)*16+i*32)+'" text-anchor="middle" font-size="28" font-weight="700" fill="#fff">'+esc(l)+'</text>'});
 return '<?xml version="1.0" encoding="UTF-8"?>\n<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+W+' '+H+'" width="'+W+'" height="'+H+'" font-family="Arial, Helvetica, sans-serif"><rect width="'+W+'" height="'+H+'" fill="#eef1f6"/>'+
  '<text x="40" y="52" font-size="30" font-weight="700" fill="#14233c">Police municipale · '+esc(title)+'</text><text x="40" y="80" font-size="15" fill="#4b5873">'+items.length+' textes · carte mentale de révision</text>'+
  links+center+out+'<text x="40" y="'+(H-16)+'" font-size="13" fill="#55627a">© 2026 La Police Municipale · usage personnel, reproduction interdite. Site non officiel : vérifier la version en vigueur sur Légifrance.</text></svg>';
}
var MAPS=[
 {id:'ensemble',t:'Vue d’ensemble',d:'Tous les textes, rangés par catégorie.',f:function(){return mapSvg()}},
 {id:'codes',t:'Les codes',d:'CGCT, CSI, CPP, Code de la route…',f:function(){return catSvg('Les codes',['Codes'],MMCOL['Codes'])}},
 {id:'lois',t:'Les lois',d:'De la loi du 15 avril 1999 aux lois récentes.',f:function(){return catSvg('Les lois',['Lois','Réforme en cours'],MMCOL['Lois'])}},
 {id:'decrets',t:'Décrets et arrêtés',d:'Armement, tenue, formation, concours…',f:function(){return catSvg('Décrets et arrêtés',['Décrets','Arrêtés'],MMCOL['Décrets et arrêtés'])}},
 {id:'articles',t:'Les articles',d:'Les articles à connaître, code par code.',f:function(){return catSvg('Les articles',['Articles'],MMCOL['Articles'])}}
];
function svgToPng(svg){
 return new Promise(function(res,rej){
  var m=svg.match(/width="(\d+)" height="(\d+)"/),w=+m[1],h=+m[2],k=Math.min(2,4000/Math.max(w,h));
  var img=new Image();img.onload=function(){try{var c=document.createElement('canvas');c.width=Math.round(w*k);c.height=Math.round(h*k);var x=c.getContext('2d');x.fillStyle='#eef1f6';x.fillRect(0,0,c.width,c.height);x.drawImage(img,0,0,c.width,c.height);c.toBlob(function(b){b?res(b):rej()},'image/png')}catch(e){rej(e)}};
  img.onerror=rej;img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
 });
}
function renderMaps(){
 var g=document.getElementById('mmGrid');if(!g||g.firstChild)return;
 MAPS.forEach(function(M){
  var svg=M.f(),card=document.createElement('div');card.className='mm';
  var fig=document.createElement('a');fig.className='mmprev';fig.href='#';fig.setAttribute('aria-label','Agrandir la carte « '+M.t+' »');
  var im=document.createElement('img');im.alt='Carte mentale : '+M.t;im.loading='lazy';im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);fig.appendChild(im);
  fig.onclick=function(e){e.preventDefault();openMM(M,svg)};
  card.appendChild(fig);
  var h=document.createElement('h3');h.textContent=M.t;card.appendChild(h);
  var p=document.createElement('p');p.textContent=M.d;card.appendChild(p);
  var row=document.createElement('div');row.className='mmbtn';
  var msg=document.createElement('div');msg.className='fb';msg.setAttribute('aria-live','polite');
  var b1=document.createElement('button');b1.type='button';b1.className='go';b1.textContent='Télécharger PNG';
  b1.onclick=async function(){msg.textContent='Préparation de l’image…';try{var blob=await svgToPng(svg);saveMsg(await saveFile('carte-mentale-'+M.id+'.png',blob,'image/png'),msg,'Image enregistrée.')}catch(e){msg.textContent='L’image n’a pas pu être créée. Essaie le SVG.'}};
  var b2=document.createElement('button');b2.type='button';b2.className='go ghost';b2.textContent='SVG';b2.setAttribute('aria-label','Télécharger en SVG');
  b2.onclick=async function(){saveMsg(await saveFile('carte-mentale-'+M.id+'.svg',svg,'image/svg+xml'),msg,'Carte enregistrée.')};
  row.appendChild(b1);row.appendChild(b2);card.appendChild(row);card.appendChild(msg);g.appendChild(card);
 });
}
var mmDlg=null;
function openMM(M,svg){
 if(!mmDlg){mmDlg=document.createElement('dialog');mmDlg.className='mmdlg';mmDlg.innerHTML='<div class="mmhead"><b></b><button type="button" class="go ghost" value="close">Fermer</button></div><div class="mmbody"></div>';document.body.appendChild(mmDlg);mmDlg.querySelector('button').onclick=function(){mmDlg.close()};mmDlg.addEventListener('click',function(e){if(e.target===mmDlg)mmDlg.close()})}
 mmDlg.querySelector('b').textContent=M.t;var b=mmDlg.querySelector('.mmbody');b.innerHTML='';var im=document.createElement('img');im.alt='Carte mentale : '+M.t;im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);b.appendChild(im);
 svgToPng(svg).then(function(blob){im.src=URL.createObjectURL(blob)}).catch(function(){});
 if(mmDlg.showModal)mmDlg.showModal();
}

