var TOUR=[
 ['Bienvenue !','Ce site t’aide à réviser la police municipale : les lois, les articles, des quiz et des outils pour le concours.'],
 ['Quatre espaces','Tout est rangé dans <b>Apprendre</b>, <b>S’entraîner</b>, <b>Explorer</b> et <b>Mes outils</b>. Ouvre-les avec le bouton <span class="kbd">☰</span> en haut à droite.'],
 ['Se repérer','En haut de chaque page, une barre montre les pages voisines. La loupe <span class="kbd">🔍</span> cherche dans tout le site. L’étoile <span class="kbd">☆</span> garde un texte dans tes favoris.'],
 ['Par où commencer ?','Lis d’abord les <b>Textes de lois</b>, puis entraîne-toi avec le <b>quiz</b>. Tes favoris, notes et scores restent sur ton appareil. Tu peux revoir ce guide à tout moment avec le bouton <span class="kbd">?</span>.']
];
var tourDlg=null,tourI=0;
function tourShow(){
 var s=TOUR[tourI];tourDlg.querySelector('h2').textContent=s[0];tourDlg.querySelector('.tbody').innerHTML=s[1];
 tourDlg.querySelector('.tdots').innerHTML=TOUR.map(function(_,i){return '<i'+(i===tourI?' class="on"':'')+'></i>'}).join('');
 tourDlg.querySelector('#tNext').textContent=tourI===TOUR.length-1?'C’est parti':'Suivant';
 tourDlg.querySelector('#tPrev').hidden=tourI===0;
}
function openTour(){
 if(!tourDlg){
  tourDlg=document.createElement('dialog');tourDlg.className='tour';tourDlg.setAttribute('aria-labelledby','tourT');tourDlg.setAttribute('data-nosnippet','');
  tourDlg.innerHTML='<div class="tflag" aria-hidden="true"></div><h2 id="tourT"></h2><div class="tbody"></div><div class="tdots" aria-hidden="true"></div><div class="tact"><button type="button" class="go ghost" id="tSkip">Passer</button><span></span><button type="button" class="go ghost" id="tPrev">Retour</button><button type="button" class="go" id="tNext">Suivant</button></div>';
  document.body.appendChild(tourDlg);
  tourDlg.querySelector('#tSkip').onclick=closeTour;
  tourDlg.querySelector('#tPrev').onclick=function(){if(tourI>0){tourI--;tourShow()}};
  tourDlg.querySelector('#tNext').onclick=function(){if(tourI<TOUR.length-1){tourI++;tourShow()}else closeTour()};
  tourDlg.addEventListener('cancel',function(){store('tuto',1)});
 }
 tourI=0;tourShow();if(tourDlg.showModal)tourDlg.showModal();
}
function closeTour(){store('tuto',1);tourDlg.close()}
document.getElementById('helpBtn').onclick=openTour;
document.getElementById('tourAgain').onclick=openTour;

