/* ---------- Protection contre la copie (dissuasion) ---------- */
(function(){
 function free(t){return t&&t.closest&&t.closest('input,textarea,[contenteditable],.mmbody')}
 document.addEventListener('contextmenu',function(e){if(!free(e.target))e.preventDefault()});
 document.addEventListener('copy',function(e){if(!free(e.target))e.preventDefault()});
 document.addEventListener('cut',function(e){if(!free(e.target))e.preventDefault()});
 document.addEventListener('dragstart',function(e){if(!free(e.target))e.preventDefault()});
 document.addEventListener('keydown',function(e){var k=(e.key||'').toLowerCase();if((e.ctrlKey||e.metaKey)&&(k==='s'||k==='u'||(k==='a'&&!free(e.target))))e.preventDefault()});
})();

try{var h=location.hash.slice(1);if(/^[dc]-/.test(h))ensureData(function(){if(/^d-/.test(h)){if(PREF[h.slice(2)])openDep(h.slice(2))}else if(BYCODE[h.slice(2)])openCommune(h.slice(2))});else if(h)go(h)}catch(x){}
